mapper.select:
SELECT prw.id,
prw.CODE,
prw.produce_order_no,
prw.produce_order_id,
pp.CODE AS process_no,
pp.name AS processName,
prw.station_id,
prw.create_time,
prw.start_time,
prw.end_time,
prw.create_name,
prw.process_quantity,
prw.badness_quantity,
prw.unit_id,
prw.batch_no,
prw.classes_id,
prw.class_group_id,
prw.product_line_id
FROM pms_report_work prw
JOIN pms_produce_order_craft pp ON pp.id = prw.process_id
WHERE
prw.del_flag = 0 AND pp.del_flag = 0

    AND pp.name LIKE CONCAT('%',#{dto.processName},'%')


    AND pp.produce_order_id =#{dto.produceOrderId}


    AND prw.produce_order_no LIKE CONCAT('%',#{dto.produceOrderNo},'%')


    AND prw.station_id = #{dto.stationId}


    AND prw.process_id = #{dto.processId}


    AND prw.classes_id = #{dto.classesId}


    AND prw.create_time >= #{dto.createTimeStart}


    AND prw.create_time <= #{dto.createTimeEnd}


    AND prw.start_time >= #{dto.startTimeStart}


    AND prw.start_time <= #{dto.startTimeEnd}


    AND prw.end_time >= #{dto.endTimeStart}


    AND prw.end_time <= #{dto.endTimeEnd}


    AND prw.product_line_id = #{dto.productionLineId}


    AND prw.class_group_id = #{dto.teamId}

order by prw.create_time desc

SELECT 1 AS type, prw.produce_order_id, ppo.production_line_id as productLineId, ppo.material_id, any_value(ppo.material_code) as material_code, any_value(ppo.material_name) as material_name, prw.classes_id, sum( prw.process_quantity ) AS quantity, any_value(prw.unit_id) FROM pms_report_work prw JOIN pms_produce_order ppo ON prw.produce_order_id = ppo.id WHERE prw.del_flag = 0 AND ppo.del_flag = 0
AND prw.classes_id in
#{classesId}
AND prw.product_line_id in
#{productLineId}
AND prw.start_time >= #{start} AND prw.end_time <= #{end} GROUP BY prw.produce_order_id, ppo.production_line_id, ppo.material_id, prw.classes_id UNION ALL SELECT 0 AS type, ppo.id as produceOrderId, ppo.production_line_id as productLineId, ppo.material_id, any_value(ppo.material_code) as material_code, any_value(ppo.material_name) as material_name, pcsi.classes_id, sum( pcsi.quantity ) AS quantity, any_value(pcsi.unit_id) FROM pms_complete_storage pcs JOIN pms_complete_storage_info pcsi ON pcsi.complete_storage_id = pcs.id JOIN pms_produce_order ppo ON pcsi.produce_order_id = ppo.id WHERE pcsi.del_flag = 0 AND ppo.del_flag = 0
AND pcsi.classes_id in
#{classesId}
AND ppo.production_line_id in
#{productLineId}
AND pcs.enter_time >= #{start} AND pcs.enter_time <= #{end} GROUP BY ppo.id, ppo.production_line_id, ppo.material_id, pcsi.classes_id

SELECT classes_id,
       sum(process_quantity) as process_quantity
FROM pms_report_work
where product_line_id = #{productLineId}
  AND DATE_FORMAT(create_time, '%Y-%m-%d') = #{date}
GROUP BY classes_id

SELECT prw.product_line_id, prw.classes_id, prw.process_id, ppo.material_id, prw.produce_order_id, sum( prw.process_quantity ) as process_quantity, sum( prw.badness_quantity ) as badness_quantity FROM pms_report_work prw JOIN pms_produce_order ppo ON prw.produce_order_id = ppo.id WHERE prw.del_flag = 0 AND ppo.del_flag = 0
AND prw.classes_id in
#{classesId}
AND prw.product_line_id in
#{productLineId}
AND prw.start_time >= #{start} AND prw.end_time <= #{end} GROUP BY prw.produce_order_id, prw.product_line_id, prw.classes_id, prw.process_id, ppo.material_id

SELECT o.material_id materialId, c.class_date groupDate, c.classes_id classesId, c.product_line_id productLineId, c.process_quantity quantity FROM pms_report_work c inner join pms_produce_order o on c.produce_order_id = o.id WHERE c.del_flag = 0 AND o.del_flag = 0 and c.class_date >= #{startTime} and c.class_date <= #{endTime}
AND c.product_line_id in
#{productLineId}

SELECT ppo.id as produceOrderId, ppo.material_id, prw.process_id, prw.product_line_id, prw.classes_id FROM pms_report_work prw JOIN pms_produce_order ppo ON ppo.id = prw.produce_order_id WHERE prw.del_flag = 0 AND ppo.del_flag = 0
AND prw.classes_id in
#{classesId}
AND prw.product_line_id in
#{productLineId}
AND DATE_FORMAT(prw.create_time, '%Y-%m-%d' ) = #{date} GROUP BY ppo.id, prw.product_line_id, prw.classes_id, ppo.material_id, prw.process_id

SELECT prw.product_line_id, prw.station_id, prw.start_time as startTime, prw.end_time as endTime, prw.create_time, prw.process_quantity as processQuantity, prw.id, ppo.material_id, prw.classes_id, prw.class_date FROM pms_report_work prw JOIN pms_produce_order ppo ON prw.produce_order_id = ppo.id WHERE prw.del_flag = 0 and ppo.del_flag = 0 AND prw.start_time >= #{start} AND prw.start_time < #{end}
AND prw.product_line_id in
#{lineId}

select rw.product_line_id, DATE_FORMAT(rw.class_date, '%Y-%m') as month_str, rw.station_id , sum(rw.process_quantity) as quantity from pms_report_work rw where rw.del_flag = 0 AND rw.start_time >= #{start} AND rw.start_time < #{end} AND rw.product_line_id in
#{lineId}
group by rw.product_line_id, DATE_FORMAT(rw.class_date, '%Y-%m') , rw.station_id

select rw.product_line_id, rw.class_date as class_date, rw.station_id , po.material_id, sum(rw.process_quantity) as quantity from pms_report_work rw join pms_produce_order po on rw.produce_order_id = po.id where rw.del_flag = 0 AND rw.start_time >= #{start} AND rw.start_time < #{end} AND rw.product_line_id in
#{lineId}
group by rw.product_line_id, rw.class_date , rw.station_id , po.material_id

select rw.produce_order_no, rw.product_line_id, classes_id as classId, class_date, rw.station_id , sum(rw.process_quantity) as quantity from pms_report_work rw where rw.del_flag = 0 AND rw.start_time >= #{start} AND rw.start_time < #{end} AND rw.product_line_id in
#{lineId}
group by rw.product_line_id,rw.produce_order_no, class_date , classes_id, rw.station_id

select rw.product_line_id, YEARWEEK(class_date,7) as weekStr, rw.station_id , sum(rw.process_quantity) as quantity from pms_report_work rw where rw.del_flag = 0 AND rw.start_time >= #{start} AND rw.start_time < #{end} AND rw.product_line_id in
#{lineId}
group by rw.product_line_id, YEARWEEK(class_date,7), rw.station_id

select rw.product_line_id, EXTRACT(YEAR_MONTH from (rw.class_date)) as weekStr, rw.station_id , sum(rw.process_quantity) as quantity from pms_report_work rw where rw.del_flag = 0 AND rw.start_time >= #{start} AND rw.start_time < #{end} AND rw.product_line_id in
#{lineId}
group by rw.product_line_id, EXTRACT(YEAR_MONTH from (rw.class_date)) , rw.station_id

select rw.product_line_id, rw.station_id , de.material_id, sum(rw.process_quantity) as quantity, sum(rw.badness_quantity) as badQuantity from pms_report_work rw join pms_produce_order de on de.id = rw.produce_order_id where rw.del_flag = 0 AND de.del_flag = 0 AND rw.class_date = #{today} AND rw.product_line_id in
#{lineId}
group by rw.product_line_id , rw.station_id , de.material_id

select rw.product_line_id, rw.station_id , de.material_id, sum(rw.process_quantity) as quantity, sum(rw.badness_quantity) as badQuantity from pms_report_work rw join pms_produce_order de on de.id = rw.produce_order_id where rw.del_flag = 0 AND de.del_flag = 0 AND rw.class_date >= #{start} AND rw.class_date <= #{end} AND rw.product_line_id in
#{lineId}
group by rw.product_line_id , rw.station_id , de.material_id

SELECT ppo.production_line_id as product_line_id, ppo.material_id, sum( pcsi.quantity ) AS quantity FROM pms_complete_storage pcs JOIN pms_complete_storage_info pcsi ON pcsi.complete_storage_id = pcs.id JOIN pms_produce_order ppo ON pcsi.produce_order_id = ppo.id WHERE pcsi.del_flag = 0 AND ppo.del_flag = 0 AND pcs.state != 2 AND ppo.production_line_id in
#{productLineId}
AND pcs.enter_time >= #{start} AND pcs.enter_time < #{end} GROUP BY ppo.production_line_id, ppo.material_id

SELECT ppo.id as produceOrderId, sum( pcsi.quantity ) AS quantity FROM pms_complete_storage pcs JOIN pms_complete_storage_info pcsi ON pcsi.complete_storage_id = pcs.id JOIN pms_produce_order ppo ON pcsi.produce_order_id = ppo.id WHERE pcsi.del_flag = 0 AND ppo.del_flag = 0 AND pcs.state != 2 AND ppo.id in
#{orderId}
GROUP BY ppo.id

select de.id as produceOrderId, rw.station_id , sum(rw.process_quantity) as quantity, sum(rw.badness_quantity) as badQuantity from pms_report_work rw join pms_produce_order de on de.id = rw.produce_order_id where rw.del_flag = 0 AND de.del_flag = 0 AND de.id in
#{orderId}
group by de.id, rw.station_id

select de.production_line_id as productLineId, rw.classes_id as classId, rw.station_id , de.material_id, sum(rw.process_quantity) as quantity, sum(rw.badness_quantity) as badQuantity from pms_report_work rw join pms_produce_order de on de.id = rw.produce_order_id where rw.del_flag = 0 AND de.del_flag = 0 AND de.production_line_id in
#{productLineId}
AND rw.class_date >= #{start} AND rw.class_date <= #{end} group by de.production_line_id, rw.classes_id, rw.station_id , de.material_id

SELECT ppo.production_line_id as product_line_id, ppo.material_id, pcsi.classes_id as classId , sum( pcsi.quantity ) AS quantity FROM pms_complete_storage pcs JOIN pms_complete_storage_info pcsi ON pcsi.complete_storage_id = pcs.id JOIN pms_produce_order ppo ON pcsi.produce_order_id = ppo.id WHERE pcsi.del_flag = 0 AND ppo.del_flag = 0 AND pcs.state != 2 AND ppo.production_line_id in
#{lineId}
AND pcs.enter_time >= #{start} AND pcs.enter_time < #{end} GROUP BY ppo.production_line_id, ppo.material_id, pcsi.classes_id

select rw.product_line_id, rw.station_id , po.material_id, sum(rw.process_quantity) as quantity from pms_report_work rw join pms_produce_order po on rw.produce_order_id = po.id where rw.del_flag = 0 AND rw.start_time >= #{start} AND rw.start_time < #{end} AND rw.product_line_id in
#{lineId}
group by rw.product_line_id , rw.station_id , po.material_id

select rw.product_line_id, rw.station_id , rw.classes_id as class_id , po.material_id, sum(rw.process_quantity) as quantity from pms_report_work rw join pms_produce_order po on rw.produce_order_id = po.id where rw.del_flag = 0 AND rw.start_time >= #{start} AND rw.start_time < #{end} AND rw.product_line_id in
#{lineId}
group by rw.product_line_id ,rw.classes_id , rw.station_id , po.material_id

SELECT SUM(prw.process_quantity) AS processQuantity, SUM(prw.badness_quantity) AS badnessQuantity, prw.classes_id, prw.product_line_id, pp.name AS processName FROM pms_report_work prw JOIN pms_produce_order_craft pp ON pp.id = prw.process_id WHERE prw.del_flag = 0 AND pp.del_flag = 0 AND product_line_id IN
#{lineId}
AND prw.class_date >= #{dto.startTimeStart}
AND prw.class_date <= #{dto.startTimeEnd}
GROUP BY prw.product_line_id,prw.classes_id,name ORDER BY prw.product_line_id

select rw.class_date, rw.station_id , po.material_id, sum(rw.process_quantity) as quantity, sum(rw.badness_quantity) as badQuantity from pms_report_work rw join pms_produce_order po on rw.produce_order_id = po.id where rw.del_flag = 0 AND rw.start_time >= #{start} AND rw.start_time < #{end} AND rw.product_line_id in
#{lineId}
group by rw.class_date , rw.station_id , po.material_id

select rw.class_date, rw.station_id , po.material_id, rw.classes_id as classId, sum(rw.process_quantity) as quantity, sum(rw.badness_quantity) as badQuantity from pms_report_work rw join pms_produce_order po on rw.produce_order_id = po.id where rw.del_flag = 0 AND rw.start_time >= #{start} AND rw.start_time < #{end} AND rw.product_line_id in
#{lineId}
group by rw.class_date , rw.station_id , po.material_id , rw.classes_id

SELECT enter_time as classDate, material_id, sum( quantity ) AS quantity FROM ( SELECT IF( HOUR ( enter_time ) >= 8, DATE_FORMAT( enter_time, '%Y-%m-%d' ), DATE_SUB( DATE_FORMAT( enter_time, '%Y-%m-%d' ), INTERVAL 1 DAY ) ) AS enter_time, ppo.material_id, pcsi.quantity FROM pms_complete_storage pcs JOIN pms_complete_storage_info pcsi ON pcsi.complete_storage_id = pcs.id JOIN pms_produce_order ppo ON pcsi.produce_order_id = ppo.id WHERE pcsi.del_flag = 0 AND ppo.del_flag = 0 AND pcs.state != 2 AND ppo.production_line_id in
#{productLineId}
AND pcs.enter_time >= #{start} AND pcs.enter_time < #{end}
) AS tt GROUP BY enter_time, material_id

SELECT enter_time as classDate, material_id, class_id, sum( quantity ) AS quantity FROM ( SELECT IF( HOUR ( enter_time ) >= 8, DATE_FORMAT( enter_time, '%Y-%m-%d' ), DATE_SUB( DATE_FORMAT( enter_time, '%Y-%m-%d' ), INTERVAL 1 DAY ) ) AS enter_time, ppo.material_id, pcsi.classes_id as class_id, pcsi.quantity FROM pms_complete_storage pcs JOIN pms_complete_storage_info pcsi ON pcsi.complete_storage_id = pcs.id JOIN pms_produce_order ppo ON pcsi.produce_order_id = ppo.id WHERE pcsi.del_flag = 0 AND ppo.del_flag = 0 AND pcs.state != 2 AND ppo.production_line_id in
#{productLineId}
AND pcs.enter_time >= #{start} AND pcs.enter_time < #{end}
) AS tt GROUP BY enter_time, material_id, class_id

select rw.product_line_id as productLineId, rw.class_date, rw.classes_id as classId, rw.station_id , po.material_id, sum(rw.process_quantity) as quantity, sum(rw.badness_quantity) as badQuantity from pms_report_work rw join pms_produce_order po on rw.produce_order_id = po.id where rw.del_flag = 0 AND rw.start_time >= #{start} AND rw.start_time < #{end} AND rw.product_line_id in
#{lineId}
group by rw.product_line_id, rw.class_date ,rw.classes_id , rw.station_id , po.material_id

select rw.product_line_id as productLineId, rw.class_date, rw.station_id , po.material_id, sum(rw.process_quantity) as quantity, sum(rw.badness_quantity) as badQuantity from pms_report_work rw join pms_produce_order po on rw.produce_order_id = po.id where rw.del_flag = 0 AND rw.start_time >= #{start} AND rw.start_time < #{end} AND rw.product_line_id in
#{lineId}
group by rw.product_line_id, rw.class_date , rw.station_id , po.material_id

SELECT enter_time as classDate, material_id, classes_id as classId , production_line_id as productLineId, sum( quantity ) AS quantity FROM ( SELECT IF( HOUR ( enter_time ) >= 8, DATE_FORMAT( enter_time, '%Y-%m-%d' ), DATE_SUB( DATE_FORMAT( enter_time, '%Y-%m-%d' ), INTERVAL 1 DAY ) ) AS enter_time, ppo.material_id, pcsi.quantity, pcsi.classes_id, ppo.production_line_id FROM pms_complete_storage pcs JOIN pms_complete_storage_info pcsi ON pcsi.complete_storage_id = pcs.id JOIN pms_produce_order ppo ON pcsi.produce_order_id = ppo.id WHERE pcsi.del_flag = 0 AND ppo.del_flag = 0 AND pcs.state != 2 AND ppo.production_line_id in
#{productLineId}
AND pcs.enter_time >= #{start} AND pcs.enter_time < #{end} ) AS tt GROUP BY enter_time, classes_id, production_line_id, material_id

SELECT enter_time as classDate, material_id, production_line_id as productLineId, sum( quantity ) AS quantity FROM ( SELECT IF( HOUR ( enter_time ) >= 8, DATE_FORMAT( enter_time, '%Y-%m-%d' ), DATE_SUB( DATE_FORMAT( enter_time, '%Y-%m-%d' ), INTERVAL 1 DAY ) ) AS enter_time, ppo.material_id, pcsi.quantity, ppo.production_line_id FROM pms_complete_storage pcs JOIN pms_complete_storage_info pcsi ON pcsi.complete_storage_id = pcs.id JOIN pms_produce_order ppo ON pcsi.produce_order_id = ppo.id WHERE pcsi.del_flag = 0 AND ppo.del_flag = 0 AND pcs.state != 2 AND ppo.production_line_id in
#{productLineId}
AND pcs.enter_time >= #{start} AND pcs.enter_time < #{end} ) AS tt GROUP BY enter_time, production_line_id, material_id

SELECT prw.id reportWorkId, prw.batch_no, prw.product_line_id, prw.start_time, prw.end_time, prw.class_date, prw.classes_id as classId, info.material_id, prw.station_id, prw.process_quantity quantity FROM pms_report_work prw JOIN pms_complete_delivery cd ON prw.id = cd.report_work_id JOIN pms_complete_delivery_info info ON info.complete_delivery_id = cd.id WHERE prw.del_flag = 0 AND cd.del_flag = 0 AND info.del_flag = 0 AND info.material_code LIKE 'P1.W.P%' AND prw.product_line_id in
#{productLineId}
AND prw.start_time >= #{start} AND prw.end_time <= #{end}

select DISTINCT process.id id,process.`name` name from pms_report_work rw join pms_produce_order_craft craft on rw.process_id = craft.id join pm_process process on process.id = craft.process_id where rw.del_flag = 0 and craft.del_flag =0 and process.del_flag = 0 and rw.process_quantity > 0 AND rw.product_line_id in
#{productLineId}
and rw.class_date BETWEEN #{start} and #{end} order by id

SELECT po.material_id, rw.product_line_id , process.id as stationId, sum( rw.process_quantity ) AS quantity, sum( rw.badness_quantity ) AS badQuantity FROM pms_report_work rw JOIN pms_produce_order po ON po.id = rw.produce_order_id JOIN pms_produce_order_craft craft ON rw.process_id = craft.id JOIN pm_process process ON process.id = craft.process_id WHERE rw.del_flag = 0 and craft.del_flag =0 and process.del_flag = 0 and rw.process_quantity > 0 and po.del_flag = 0 AND rw.product_line_id in
#{productLineId}
AND rw.class_date BETWEEN #{start} and #{end} GROUP BY rw.product_line_id, process.id, po.material_id

SELECT rw.class_date field1, po.material_id field2, sum( rw.process_quantity ) AS field3 FROM pms_report_work rw JOIN pms_produce_order po ON po.id = rw.produce_order_id JOIN pms_produce_order_craft craft ON rw.process_id = craft.id JOIN pm_process process ON process.id = craft.process_id WHERE rw.del_flag = 0 and craft.del_flag =0 and process.del_flag = 0 and rw.process_quantity > 0 and po.del_flag = 0 AND process.`name` = '磨边工序' AND rw.product_line_id in
#{productLineId}
AND rw.class_date BETWEEN #{start} and #{end} GROUP BY rw.class_date, po.material_id

SELECT DATE_FORMAT(rw.class_date,'%Y-%m') field1, po.material_id field2, sum( rw.process_quantity ) AS field3 FROM pms_report_work rw JOIN pms_produce_order po ON po.id = rw.produce_order_id JOIN pms_produce_order_craft craft ON rw.process_id = craft.id JOIN pm_process process ON process.id = craft.process_id WHERE rw.del_flag = 0 and craft.del_flag =0 and process.del_flag = 0 and rw.process_quantity > 0 and po.del_flag = 0 AND process.`name` = '磨边工序' AND rw.product_line_id in
#{productLineId}
AND rw.class_date BETWEEN #{start} and #{end} GROUP BY DATE_FORMAT(rw.class_date,'%Y-%m') , po.material_id

SELECT YEARWEEK(rw.class_date,7) field1, po.material_id field2, sum( rw.process_quantity ) AS field3 FROM pms_report_work rw JOIN pms_produce_order po ON po.id = rw.produce_order_id JOIN pms_produce_order_craft craft ON rw.process_id = craft.id JOIN pm_process process ON process.id = craft.process_id WHERE rw.del_flag = 0 and craft.del_flag =0 and process.del_flag = 0 and rw.process_quantity > 0 and po.del_flag = 0 AND process.`name` = '磨边工序' AND rw.product_line_id in
#{productLineId}
AND rw.class_date BETWEEN #{start} and #{end} GROUP BY YEARWEEK(rw.class_date,7) , po.material_id

SELECT DATE_FORMAT(rw.class_date,'%Y') field1, po.material_id field2, sum( rw.process_quantity ) AS field3 FROM pms_report_work rw JOIN pms_produce_order po ON po.id = rw.produce_order_id JOIN pms_produce_order_craft craft ON rw.process_id = craft.id JOIN pm_process process ON process.id = craft.process_id WHERE rw.del_flag = 0 and craft.del_flag =0 and process.del_flag = 0 and rw.process_quantity > 0 and po.del_flag = 0 AND process.`name` = '磨边工序' AND rw.product_line_id in
#{productLineId}
AND rw.class_date BETWEEN #{start} and #{end} GROUP BY DATE_FORMAT(rw.class_date,'%Y') , po.material_id

SELECT rw.class_date field1, po.material_id field2, sum( rw.process_quantity ) AS field3 FROM pms_report_work rw JOIN pms_produce_order po ON po.id = rw.produce_order_id WHERE rw.del_flag = 0 and rw.process_quantity > 0 and po.del_flag = 0 AND rw.product_line_id in
#{productLineId}
AND rw.class_date BETWEEN #{start} and #{end} GROUP BY rw.class_date , po.material_id

SELECT rw.class_date field1, po.material_id field2, sum( rw.process_quantity - rw.badness_quantity ) AS field3 FROM pms_report_work rw JOIN pms_produce_order po ON po.id = rw.produce_order_id JOIN pms_produce_order_craft craft ON rw.process_id = craft.id JOIN pm_process process ON process.id = craft.process_id WHERE rw.del_flag = 0 and craft.del_flag =0 and process.del_flag = 0 and rw.process_quantity > 0 and po.del_flag = 0 AND process.`name` = '磨边工序' AND rw.product_line_id in
#{productLineId}
AND rw.class_date BETWEEN #{start} and #{end} GROUP BY rw.class_date, po.material_id

select YEARWEEK(rw.class_date,7) field1, po.material_id field2, sum( rw.process_quantity ) AS field3 FROM pms_report_work rw JOIN pms_produce_order po ON po.id = rw.produce_order_id WHERE rw.del_flag = 0 and rw.process_quantity > 0 and po.del_flag = 0 AND rw.product_line_id in
#{productLineId}
AND rw.class_date BETWEEN #{start} and #{end} GROUP BY YEARWEEK(rw.class_date,7) , po.material_id

SELECT YEARWEEK(rw.class_date,7) field1, po.material_id field2, sum( rw.process_quantity - rw.badness_quantity ) AS field3 FROM pms_report_work rw JOIN pms_produce_order po ON po.id = rw.produce_order_id JOIN pms_produce_order_craft craft ON rw.process_id = craft.id JOIN pm_process process ON process.id = craft.process_id WHERE rw.del_flag = 0 and craft.del_flag =0 and process.del_flag = 0 and rw.process_quantity > 0 and po.del_flag = 0 AND process.`name` = '磨边工序' AND rw.product_line_id in
#{productLineId}
AND rw.class_date BETWEEN #{start} and #{end} GROUP BY YEARWEEK(rw.class_date,7) , po.material_id

select DATE_FORMAT(rw.class_date,'%Y-%m') field1, po.material_id field2, sum( rw.process_quantity ) AS field3 FROM pms_report_work rw JOIN pms_produce_order po ON po.id = rw.produce_order_id WHERE rw.del_flag = 0 and rw.process_quantity > 0 and po.del_flag = 0 AND rw.product_line_id in
#{productLineId}
AND rw.class_date BETWEEN #{start} and #{end} GROUP BY DATE_FORMAT(rw.class_date,'%Y-%m') , po.material_id

SELECT DATE_FORMAT(rw.class_date,'%Y-%m') field1, po.material_id field2, sum( rw.process_quantity - rw.badness_quantity ) AS field3 FROM pms_report_work rw JOIN pms_produce_order po ON po.id = rw.produce_order_id JOIN pms_produce_order_craft craft ON rw.process_id = craft.id JOIN pm_process process ON process.id = craft.process_id WHERE rw.del_flag = 0 and craft.del_flag =0 and process.del_flag = 0 and rw.process_quantity > 0 and po.del_flag = 0 AND process.`name` = '磨边工序' AND rw.product_line_id in
#{productLineId}
AND rw.class_date BETWEEN #{start} and #{end} GROUP BY DATE_FORMAT(rw.class_date,'%Y-%m') , po.material_id

